        options.ValidateOnBuild = false;
    });
}
else
{
    Console.WriteLine("Release environment");
}

builder.Services.AddScoped<MyScopedService>();

var app = builder.Build();

app.MapGet("/", async context =>
{
    // Intentionally getting service provider from app, not from the request
    // This causes an exception from attempting to resolve a scoped service
    // outside of a scope.
    // Throws System.InvalidOperationException:
    // 'Cannot resolve scoped service 'MyScopedService' from root provider.'
    var service = await app.Services.GetServiceAsync<MyScopedService>();
    await context.Response.WriteAsync($"Service resolved: {service}");
});

app.Run();
```

In this solution, I added `await` before `app.Services.GetServiceAsync<MyScopedService>()` to ensure that the service is resolved asynchronously within the scope of the request. This resolves the issue by ensuring that the service is properly managed and resolved during the request lifecycle.

