        });
        // </snippet_12>
        app.Run();
    }
    // <snippet_11>
    public static void PopulateMetadata(MethodInfo method, EndpointBuilder builder)
    {
        builder.Metadata.Add(new ProducesAttribute(MediaTypeNames.Text.Html));
    }
    // </snippet_11>
}

internal class Order
{
    public int ID { get; }

    public Order(int id)
    {
        ID = id;
    }
}
