    {
        context.Response.Headers[headerName] = correlationId;
        return Task.CompletedTask;
    });

    await next(); // Fix the missing closing parenthesis here
});

app.MapGet("/", (HttpContext ctx) =>
{
    var correlationId = ctx.Items["X-Correlation-ID"]?.ToString() ?? "none";
    return Results.Ok(new { Message = "Hello", CorrelationId = correlationId });
});

app.Run();
