// Program.cs

using System.Collections.Concurrent;
using System.Threading;

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

var todos = new ConcurrentDictionary<int, Todo>();
int nextId = 0;

// GET /todos
app.MapGet("/todos", () => Results.Ok(todos.Values));

// GET /todos/{id}
app.MapGet("/todos/{id:int}", (int id) =>
{
    return todos.TryGetValue(id, out var todo)
        ? Results.Ok(todo)
        : Results.NotFound();
});

// POST /todos
app.MapPost("/todos", (TodoCreateDto dto) =>
{
    var id = Interlocked.Increment(ref nextId);
    var todo = new Todo { Id = id, Title = dto.Title, IsDone = false };
    todos[id] = todo;
    return Results.Created($"/todos/{id}", todo);
});

// PUT /todos/{id}
app.MapPut("/todos/{id:int}", (int id, TodoUpdateDto dto) =>
{
    if (!todos.TryGetValue(id, out var todo))
        return Results.NotFound();

    todo.Title = dto.Title;
    todo.IsDone = dto.IsDone;
    return Results.NoContent();
});

// DELETE /todos/{id}
app.MapDelete("/todos/{id:int}", (int id) =>
{
    return todos.TryRemove(id, out _)
        ? Results.NoContent()
        : Results.NotFound();
});

app.Run();

class Todo
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public bool IsDone { get; set; }
}

record TodoCreateDto(string Title); // Changed from string Title; to string Title;
record TodoUpdateDto(string Title, bool IsDone); // Changed from string Title; to string Title;
